/**
 * Doctor command handler
 */
import { defineSchema, lazySchema } from "../../../src/schemas/index.js";
import { cwd } from "../../../src/platform/index.js";
import { doctorCommand } from "./index.js";
import { showHeader } from "../../utils/index.js";
import { createArgParser, parseArgsOrThrow } from "../../shared/args.js";
import { isJsonMode } from "../../shared/json-output.js";
const getDoctorArgsSchema = defineSchema((v) => v.object({
    strict: v.boolean().default(false),
    port: v.number().int().min(1).max(65535).optional(),
}));
const DoctorArgsSchema = lazySchema(getDoctorArgsSchema);
export const parseDoctorArgs = createArgParser(DoctorArgsSchema, {
    strict: { keys: ["strict", "s"], type: "boolean" },
    port: { keys: ["port", "p"], type: "number" },
}, { rejectUnknown: true });
export async function handleDoctorCommand(args) {
    const opts = parseArgsOrThrow(parseDoctorArgs, "doctor", args);
    if (!isJsonMode())
        showHeader();
    await doctorCommand(cwd(), opts);
}
